window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-2835c129734605ec"]={"versions": [{"id": "FIG-2835c129734605ec", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Struktur- und Mapping-Diagramm zur Veranschaulichung des Bit- und Byte-Layouts bei der Serialisierung von Software-Datenelementen in eine Kommunikations-PDU (I-PDU) im Kontext der AUTOSAR E2E-Bibliothek (End-to-End Protection). Das Diagramm stellt dar, wie softwareseitige Variablen (C-Datentypen) unvollständig bzw. versetzt in die Bytestruktur einer I-PDU abgebildet werden und welche Bereiche mit festen Füll- bzw. Maskierungswerten belegt werden.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Quell-Datenelemente (C-Typen/Variablen)</strong>:\n<ul class=\"fig-list\"><li><code>speed</code>: 16-Bit-Variable, von der 12 Bits in der I-PDU verwendet werden.\n</li><li><code>accel</code>: 16-Bit-Variable, von der 12 Bits in der I-PDU verwendet werden.\n</li></ul>\n</li><li><strong>Zielstruktur (I-PDU / Byte-Array)</strong>:\n<ul class=\"fig-list\"><li>Segmentierte Bytes/Felder innerhalb des PDU-Puffers.\n</li><li>Zielbereich für <code>accel</code> (überspannt Bytegrenzen bzw. Teilbereiche eines Bytes).\n</li><li>Zielbereich für <code>speed</code> (erstreckt sich über zwei aufeinanderfolgende Bytes/Teilbytes).\n</li><li>Unbenutzte bzw. statische Füllbereiche, vorbelegt mit konstanten Werten (<code>0xF0</code>, <code>0xFF</code>).\n</li></ul>\n</li><li><strong>Verbindungsrelationen</strong>:\n<ul class=\"fig-list\"><li>Gerichtete Pfeile verbinden die Deklarationen der Datenelemente mit ihren spezifischen Bit- und Byte-Positionen innerhalb des PDU-Puffers.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Schaubild illustriert einen statischen Mapping- und Serialisierungsvorgang:</p>\n<ol class=\"fig-list\"><li>Vor dem Berechnen von E2E-Prüfsummen oder CRC-Schutzmechanismen werden die Daten aus den C-Datenelementen (<code>speed</code>, <code>accel</code>) an definierte Bitpositionen der I-PDU kopiert.\n</li><li>Variablen mit 16-Bit-Breite, die nur partiell (12 Bits) genutzt werden, hinterlassen nicht belegte Restbits oder Lücken.\n</li><li>Nicht durch Signale abgedeckte Bits bzw. Füllbereiche werden mit definierten Konstanten (hier <code>0xF0</code> und <code>0xFF</code>) initialisiert bzw. maskiert, um deterministische Eingangsdaten für die E2E-Prüfung zu gewährleisten.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Normative Relevanz</strong>: Die Darstellung demonstriert die Notwendigkeit konsistenter Serialisierungs- und Byte-Alignment-Regeln bei E2E-geschützten I-PDUs. Da der E2E-Mechanismus Prüfsummen über den gesamten serialisierten Datenstrom berechnet, führen uninitialisierte Lückenbits zu Checksummenfehlern.\n</li><li><strong>Entwickler-Hinweise</strong>:\n<ul class=\"fig-list\"><li>Signale, die kleiner als ihr nativer Datentyp sind (z. B. 12 Bit in 16 Bit), erfordern eine deterministische Bitmaskierung und Byte-Reihenfolge (Endianness).\n</li><li>Unbenutzte Bitpositionen innerhalb geschützter I-PDU-Bereiche müssen auf Sender- und Empfängerseite mit identischen statischen Bitmustern (z. B. <code>0xFF</code> / <code>0xF0</code>) belegt sein, damit die CRC-Verifikation der E2E-Bibliothek fehlerfrei arbeitet.\n</li></ul>\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-7f10a8ef998b1292", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Struktur- und Mapping-Diagramm zur Veranschaulichung des Bit- und Byte-Layouts bei der Serialisierung von Software-Datenelementen in eine Kommunikations-PDU (I-PDU) im Kontext der AUTOSAR E2E-Bibliothek (End-to-End Protection). Das Diagramm stellt dar, wie softwareseitige Variablen (C-Datentypen) unvollständig bzw. versetzt in die Bytestruktur einer I-PDU abgebildet werden und welche Bereiche mit festen Füll- bzw. Maskierungswerten belegt werden.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Quell-Datenelemente (C-Typen/Variablen)</strong>:\n<ul class=\"fig-list\"><li><code>speed</code>: 16-Bit-Variable, von der 12 Bits in der I-PDU verwendet werden.\n</li><li><code>accel</code>: 16-Bit-Variable, von der 12 Bits in der I-PDU verwendet werden.\n</li></ul>\n</li><li><strong>Zielstruktur (I-PDU / Byte-Array)</strong>:\n<ul class=\"fig-list\"><li>Segmentierte Bytes/Felder innerhalb des PDU-Puffers.\n</li><li>Zielbereich für <code>accel</code> (überspannt Bytegrenzen bzw. Teilbereiche eines Bytes).\n</li><li>Zielbereich für <code>speed</code> (erstreckt sich über zwei aufeinanderfolgende Bytes/Teilbytes).\n</li><li>Unbenutzte bzw. statische Füllbereiche, vorbelegt mit konstanten Werten (<code>0xF0</code>, <code>0xFF</code>).\n</li></ul>\n</li><li><strong>Verbindungsrelationen</strong>:\n<ul class=\"fig-list\"><li>Gerichtete Pfeile verbinden die Deklarationen der Datenelemente mit ihren spezifischen Bit- und Byte-Positionen innerhalb des PDU-Puffers.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Schaubild illustriert einen statischen Mapping- und Serialisierungsvorgang:</p>\n<ol class=\"fig-list\"><li>Vor dem Berechnen von E2E-Prüfsummen oder CRC-Schutzmechanismen werden die Daten aus den C-Datenelementen (<code>speed</code>, <code>accel</code>) an definierte Bitpositionen der I-PDU kopiert.\n</li><li>Variablen mit 16-Bit-Breite, die nur partiell (12 Bits) genutzt werden, hinterlassen nicht belegte Restbits oder Lücken.\n</li><li>Nicht durch Signale abgedeckte Bits bzw. Füllbereiche werden mit definierten Konstanten (hier <code>0xF0</code> und <code>0xFF</code>) initialisiert bzw. maskiert, um deterministische Eingangsdaten für die E2E-Prüfung zu gewährleisten.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Normative Relevanz</strong>: Die Darstellung demonstriert die Notwendigkeit konsistenter Serialisierungs- und Byte-Alignment-Regeln bei E2E-geschützten I-PDUs. Da der E2E-Mechanismus Prüfsummen über den gesamten serialisierten Datenstrom berechnet, führen uninitialisierte Lückenbits zu Checksummenfehlern.\n</li><li><strong>Entwickler-Hinweise</strong>:\n<ul class=\"fig-list\"><li>Signale, die kleiner als ihr nativer Datentyp sind (z. B. 12 Bit in 16 Bit), erfordern eine deterministische Bitmaskierung und Byte-Reihenfolge (Endianness).\n</li><li>Unbenutzte Bitpositionen innerhalb geschützter I-PDU-Bereiche müssen auf Sender- und Empfängerseite mit identischen statischen Bitmustern (z. B. <code>0xFF</code> / <code>0xF0</code>) belegt sein, damit die CRC-Verifikation der E2E-Bibliothek fehlerfrei arbeitet.\n</li></ul>\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-2835c129734605ec", "to": "FIG-7f10a8ef998b1292", "fr": "R3.2.3", "tr": "R4.1.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
